using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing Serilog;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetStoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetStoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a POST request with the new pet data\")]\n        public void WhenISendAPostRequestWithTheNewPetData()\n        {\n            var newPet = new { id = 123, name = \"Doggie\", status = \"available\" };\n            _response = _petApiHelper.SendPostRequest((string)_scenarioContext[\"Endpoint\"], newPet);\n            Log.Information(\"POST request sent with payload: {Payload}\", newPet);\n        }\n\n        [When(\"I send a GET request for the pet\")]\n        public void WhenISendAGetRequestForThePet()\n        {\n            _response = _petApiHelper.SendGetRequest((string)_scenarioContext[\"Endpoint\"]);\n            Log.Information(\"GET request sent to endpoint: {Endpoint}\", _scenarioContext[\"Endpoint\"]);\n        }\n\n        [When(\"I send a PUT request with updated pet data\")]\n        public void WhenISendAPutRequestWithUpdatedPetData()\n        {\n            var updatedPet = new { id = 123, name = \"Doggie\", status = \"sold\" };\n            _response = _petApiHelper.SendPutRequest((string)_scenarioContext[\"Endpoint\"], updatedPet);\n            Log.Information(\"PUT request sent with payload: {Payload}\", updatedPet);\n        }\n\n        [When(\"I send a DELETE request for the pet\")]\n        public void WhenISendADeleteRequestForThePet()\n        {\n            _response = _petApiHelper.SendDeleteRequest((string)_scenarioContext[\"Endpoint\"]);\n            Log.Information(\"DELETE request sent to endpoint: {Endpoint}\", _scenarioContext[\"Endpoint\"]);\n        }\n\n        [Then(\"the response status code should be 200\")]\n        public void ThenTheResponseStatusCodeShouldBe200()\n        {\n            Assert.AreEqual(200, (int)_response.StatusCode);\n            Log.Information(\"Response status code: {StatusCode}\", _response.StatusCode);\n        }\n\n        [Then(\"the pet should be created successfully\")]\n        public void ThenThePetShouldBeCreatedSuccessfully()\n        {\n            Assert.IsNot